function eventCard(e){return `<button class="glass dark event-row" data-go="EVE-03" data-key="event" data-value="${e.id}">${photo('wedding')}<span><h3>${esc(e.name)}</h3><p>${dateText(e.date)}</p><small>${Object.keys(e.look||{}).length} composantes choisies</small></span>${icon('chev')}</button>`;}
