function goalCount(g){return M.sessions.filter(s=>s.ref===g.routine&&s.date>=g.date&&sessionComplete(s)).length;}
function goalCard(g){const n=goalCount(g),pc=Math.min(100,n/Math.max(1,g.target)*100),status=n>=g.target?'Objectif atteint':g.status==='closed'?'Clôturée':g.status==='paused'?'En pause':'À mon rythme';return B(`<span><h3>${esc(g.name)}</h3><p class="subtle">${n} / ${g.target} séances, ${status}</p><div class="bar"><span style="width:${pc}%"></span></div></span>${icon('chev')}`,'PRO-06','glass list-row',{key:'goal',value:g.id});}
