function calendarMove(delta){const d=new Date((M.calendarMonth||DATE().slice(0,7))+'-01T12:00:00');d.setMonth(d.getMonth()+delta);M.calendarMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');render();}

function reportDomains(r){return r.domain.startsWith('Ensemble')?DOMAINS.map(x=>x[0]):[r.domain];}
function domainAvailable(r,d){return r.status!=='partial'||reportDomains(r).indexOf(d)<(reportDomains(r).length===1?0:2);}
function answersSummary(r,d){const a=r.answers||{},p=r.prefs||{};return ({Cheveux:[a.texture||p.hair,a.time||p.time],Maquillage:[a.makeup||p.makeup,a.occasion],Colorimétrie:[a.colors||'Couleurs à explorer'],Peau:[a.skin||'Une routine selon vos envies'],'Garde-robe':[a.style||p.style,a.occasion]})[d]?.filter(Boolean).join(', ')||'Selon vos envies';}
function reportRecommendations(r){const ds=reportDomains(r).filter(d=>domainAvailable(r,d)),a=r.answers||{},source=[...CATALOG.filter(x=>['Look','Palette','Conseil'].includes(x.type)),...M.routines],score=x=>(x.texture?.includes(a.texture)?5:0)+(a.time==='Moins de 5 min'&&x.minutes<=5?3:0)+(x.occasion===a.occasion?2:0)+(a.makeup==='Sans maquillage'&&x.id==='bare-face'?8:0);const groups=ds.map(d=>source.filter(x=>x.domain===d).sort((x,y)=>score(y)-score(x)).slice(0,2));return [...groups.map(g=>g[0]),...groups.map(g=>g[1])].filter(Boolean).slice(0,6).map(x=>x.id);}
Object.assign(ACTIONS,{
 'without-photo':()=>{M.draft.photo='';M.draft.withoutPhoto=true;go('ANA-07');},
 'edit-analysis':()=>{const r=report();if(!r)return;M.draft={id:uid('draft'),domain:r.domain,photo:r.photo||'',withoutPhoto:!r.photo,answers:clone(r.answers||{}),consent:true,status:'draft',phase:'ANA-07',revises:r.id};clearDrafts('analysis-answers');go('ANA-07');},
 'delete-report-request':d=>confirmAction('Retirer ce compte rendu ?','Vos autres comptes rendus, routines et favoris seront conservés.','delete-report',d),
 'delete-report':d=>{M.analyses=M.analyses.filter(r=>r.id!==d.id);if(M.draft.reportId===d.id){M.draft=clone(initial().draft);}M.messages=M.messages.filter(m=>!(m.objectKey==='analysis'&&m.objectId===d.id));if(M.comparison?.includes(d.id))M.comparison=null;closeModal();go('ANA-12');},
 'observation-photo-remove':()=>{M.context.observationPhoto='';render();},
 'delete-observation-request':d=>confirmAction('Supprimer cette observation ?','Les autres moments de votre journal seront conservés.','delete-observation',d),
 'delete-observation':d=>{M.observations=M.observations.filter(o=>o.id!==d.id);M.observationEdit=null;if(M.comparison?.includes(d.id))M.comparison=null;closeModal();go('PRO-01');}
});
F['journal-filter']=d=>{M.journalQuery=d.q;render();};
